'use strict';
const D=window.GUARDIAN_DATA,M=window.GuardianMath,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=v=>v==null?'Indisponível':(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),pct=v=>v==null?'Indisponível':(v*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%',num=v=>v==null?'—':v.toLocaleString('pt-BR',{maximumFractionDigits:0}),pp=v=>v==null?'Indisponível':(v>0?'+':'')+(v*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+' pp',date=v=>new Date(v+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC'}),month=v=>new Date(v+'-01T12:00:00Z').toLocaleDateString('pt-BR',{month:'short',year:'numeric',timeZone:'UTC'});
const periodLabel=win=>date(win[0])+' a '+date(new Date(new Date(win[1]+'T12:00:00Z').getTime()-86400000).toISOString().slice(0,10));
const E=window.GuardianEngine, engine=E.create(D);
const initial={tab:'executive',start:'2026-10-01',end:D.as_of,category:'',type:'',sku:'',selected:'SKU-001',group:'category'};
let state={...initial},simInput=null,lastScenario='',filterMessage='';
try{const saved=JSON.parse(sessionStorage.getItem('guardian-v43')||'null');if(saved&&saved.start>=D.raw.history_start&&saved.end<=D.as_of&&saved.start<=saved.end){E.parse(saved.start);E.parse(saved.end);state={...initial,...saved};}}catch(e){}
const titles={executive:['Sua margem, em perspectiva.','O resultado de hoje, com o contexto que faltava.'],diagnostic:['Do sinal à evidência.','Investigue a margem e compare o mesmo produto ao longo do tempo.'],simulator:['Explore antes de decidir.','Premissas claras para testar decisões, com o histórico sempre à vista.']};
function snapshot(){return engine.analyze(state.start,E.add(state.end,1));}
function persist(){try{sessionStorage.setItem('guardian-v43',JSON.stringify(state));}catch(e){}}
function filter(i){return(!state.category||i.category===state.category)&&(!state.type||i.type===state.type)&&(!state.sku||i.sku===state.sku);}
function selectedItems(){return snapshot().items.filter(filter);}
function selectedItem(){const items=selectedItems().filter(i=>i.current.count);return items.find(i=>i.sku===state.selected)||items[0];}
function choose(sku,tab){state.selected=sku;state.tab=tab;simInput=null;render();$('main').focus();}
function notice(text,style=''){return `<div class="notice ${style}">${text}</div>`;}
function kpi(label,value,note,featured=false){return `<div class="card kpi ${featured?'featured':''}"><label>${label}</label><div class="value">${value}</div><div class="small">${note}</div></div>`;}
function empty(){return `<section class="card empty"><h2>Nenhuma venda nesta seleção.</h2><p class="muted">Amplie o período ou remova os filtros de categoria, tipo e produto.</p><button class="button" data-clear>Limpar filtros</button></section>`;}
function growth(current,old){return current!=null&&old>0?pct(current/old-1):'Não aplicável';}
function options(items,selected){return items.filter(i=>i.current.count).map(i=>`<option value="${esc(i.sku)}" ${i.sku===selected?'selected':''}>${esc(i.name)} · ${i.sku}</option>`).join('');}
function chart(points,key='margin',other=null,isMoney=false,third=null){
 const available=points.flatMap(p=>[p[key],other?p[other]:null,third?p[third]:null]).filter(v=>v!=null&&Number.isFinite(v));if(!available.length)return '<p class="small">Sem histórico elegível para desenhar a curva.</p>';
 let min=Math.min(...available),max=Math.max(...available);const span=max-min||.1;min-=span*.25;max+=span*.25;
 const w=650,h=230,left=64,right=22,top=22,bottom=36,x=i=>points.length===1?w/2:left+i*(w-left-right)/(points.length-1),y=v=>h-bottom-(v-min)/(max-min)*(h-top-bottom);
 let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Histórico. Valores exatos disponíveis na tabela abaixo.">`;
 for(let i=0;i<4;i++){const val=min+(max-min)*i/3;svg+=`<line x1="${left}" y1="${y(val)}" x2="${w-right}" y2="${y(val)}" stroke="#e3e5ea"/><text x="${left-9}" y="${y(val)+4}" text-anchor="end">${esc(isMoney?brl(val):pct(val))}</text>`;}
 function line(k,color,dash){let segment=[];let out='';for(let i=0;i<=points.length;i++){const p=points[i];if(p&&p[k]!=null)segment.push(`${x(i)},${y(p[k])}`);else if(segment.length){out+=`<polyline points="${segment.join(' ')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" ${dash?'stroke-dasharray="5 5"':'class="ln" pathLength="1"'}/>`;segment=[];}}return out;}
 if(third)svg+=line(third,'#976318',true);if(other)svg+=line(other,'#6872a8',true);svg+=line(key,'#087f71',false);
 points.forEach((p,i)=>{for(const [k,col] of [[other,'#6872a8'],[third,'#976318']])if(k&&p[k]!=null)svg+=`<circle cx="${x(i)}" cy="${y(p[k])}" r="3" fill="${col}"><title>${esc(k==='year'?'Ano anterior':'Referência')}: ${esc(isMoney?brl(p[k]):pct(p[k]))}</title></circle>`;svg+=`<text x="${x(i)}" y="${h-9}" text-anchor="middle">${esc(p.month.slice(5))}/${p.month.slice(2,4)}</text>`;if(p[key]!=null)svg+=`<circle tabindex="0" cx="${x(i)}" cy="${y(p[key])}" r="4" fill="#087f71"><title>${esc(month(p.month))}: ${esc(isMoney?brl(p[key]):pct(p[key]))} · Receita ${brl(p.revenue)} · LB ${brl(p.gross)} · volume ${num(p.quantity)}</title></circle>`;});return svg+'</svg>';
}
const refs=[['three','3 meses anteriores'],['year','Ano anterior']];
function comparison(items,caption='Comparativos do recorte'){
 const snap=snapshot(),a=M.aggregate(items.map(i=>i.current));
 return `<section class="comparison-section" aria-label="Comparativos históricos"><div class="section-line"><div><p class="eyebrow">CONTEXTO SEM TROCAR DE CENÁRIO</p><h2>${esc(caption)}</h2></div><span class="small">Margens ponderadas pela receita</span></div><div class="comparisons"><article class="comparison current"><div class="compare-label"><i></i> Período selecionado</div><p class="small">${periodLabel(snap.windows.current)}</p><strong>${pct(a.margin)}</strong><span class="small">margem bruta realizada</span><div class="compare-metrics"><span>Receita <b>${brl(a.revenue)}</b></span><span>LB elegível <b>${brl(a.gross)}</b></span><span>Cobertura CMV <b>${pct(a.coverage)}</b></span></div></article>${refs.map(([ref,label])=>{const b=M.aggregate(items.map(i=>i[ref])),ok=snap.complete[ref],delta=ok&&a.margin!=null&&b.margin!=null?a.margin-b.margin:null,days=w=>(+E.parse(w[1])-E.parse(w[0]))/86400000,same=days(snap.windows.current)===days(snap.windows[ref]);return `<article class="comparison ${ref}"><div class="compare-label"><i></i> ${label}</div><p class="small">${periodLabel(snap.windows[ref])}</p><strong>${ok?pct(b.margin):'Histórico insuficiente'}</strong><span class="delta ${delta<0?'down':delta>0?'up':''}">${delta==null?'Variação indisponível':pp(delta)+' no período selecionado'}</span><div class="compare-metrics"><span>Receita <b>${ok?brl(b.revenue):'Indisponível'}</b></span><span>LB elegível <b>${ok?brl(b.gross):'Indisponível'}</b></span><span>Cobertura CMV <b>${ok?pct(b.coverage):'Indisponível'}</b></span></div><p class="small compare-note">${!ok?'A base não cobre a janela inteira. Nenhum histórico ausente é estimado.':ref==='three'?'Total acumulado de 3 meses civis; duração diferente da seleção em geral.':same?'Receita vs ano anterior: '+growth(a.revenue,b.revenue)+'.':'Calendário ajustado (29/02 → 28/02); durações diferentes, sem % de crescimento.'}</p></article>`;}).join('')}</div></section>`;
}
function history(items){const keys=new Set(items.map(i=>i.sku)),out=[];let start=state.start.slice(0,7)+'-01';while(start<=state.end){const d=E.parse(start),next=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1)).toISOString().slice(0,10),a=start<state.start?state.start:start,b=next>E.add(state.end,1)?E.add(state.end,1):next,s=engine.analyze(a,b),part=s.items.filter(i=>keys.has(i.sku));out.push({month:start.slice(0,7),...M.aggregate(part.map(i=>i.current)),benchmark:s.complete.three?M.aggregate(part.map(i=>i.three)).margin:null,year:s.complete.year?M.aggregate(part.map(i=>i.year)).margin:null,start:a,end:b});start=next;}return out;}
function drivers(items){const snap=snapshot();return `<section class="card drivers"><div class="card-head"><div><h2>O que explica a variação</h2><p class="small">Preço, custo e composição · calculados para os produtos filtrados</p></div><span class="tag green">Efeitos em pp</span></div><div class="grid equal">${refs.map(([ref,label])=>{const dc=snap.complete[ref]?E.decompose(items,ref):null;if(!dc)return `<div><h3>Atual × ${label.toLowerCase()}</h3><p class="small">Decomposição indisponível: histórico incompleto ou sem receita e quantidade elegíveis positivas.</p></div>`;const fx=[['Preço líquido',dc.effects.price],['CMV unitário',dc.effects.cost],['Mix de produtos',dc.effects.mix],['Entrada de SKUs',dc.effects.entry]],big=Math.max(.0001,...fx.map(([,v])=>Math.abs(v))),lead=fx.reduce((a,b)=>a[1]<b[1]?a:b);return `<div><div class="driver-title"><h3>Atual × ${label.toLowerCase()}</h3><b class="${dc.total<0?'down':'up'}">${pp(dc.total)}</b></div>${fx.map(([n,v])=>`<div class="bar-row"><div class="bar-info"><span>${n}</span><b class="${v<0?'down':v>0?'up':''}">${pp(v)}</b></div><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(v)/big*100}%;background:${v<0?'var(--red)':'var(--green)'}"></div></div></div>`).join('')}<p class="small">${lead[1]<-1e-9?'Maior pressão: '+lead[0].toLowerCase()+'.':'Sem pressão negativa relevante.'} Efeitos conciliados à variação total antes do arredondamento.</p></div>`;}).join('')}</div><p class="small">Saídas de SKUs estão incluídas no mix. Decomposição matemática, não prova de causalidade. Preço antes do custo; outra ordem pode distribuir a interação de forma diferente.</p></section>`;}
function executive(items){
 if(!items.some(i=>i.current.count))return empty();const a=M.aggregate(items.map(i=>i.current)),hist=history(items),below=items.some(i=>i.current.gap!=null)?items.reduce((s,i)=>s+(i.current.gap||0),0):null;
 const signals=items.filter(i=>i.current.count&&i.alerts.length).sort((x,y)=>(y.current.gap??-1)-(x.current.gap??-1)||x.sku.localeCompare(y.sku));
 const groups={};for(const i of items){const key=state.group==='sku'?i.name:i[state.group];(groups[key]??=[]).push(i);}const grouped=Object.entries(groups).map(([name,rows])=>({name,...M.aggregate(rows.map(i=>i.current)),three:M.aggregate(rows.map(i=>i.three)),year:M.aggregate(rows.map(i=>i.year))})).sort((x,y)=>(y.gap??-1)-(x.gap??-1));
 return `<section class="kpis">${kpi('Receita líquida disponível',brl(a.revenue),num(a.count)+' registros no período')}${kpi('Margem bruta realizada',pct(a.margin),'Receita elegível: '+brl(a.eligible_revenue),true)}${kpi('Lucro bruto elegível',brl(a.gross),'Receita elegível menos CMV registrado')}${kpi('Falta para a meta · por SKU',brl(below),'Gap líquido da carteira: '+brl(a.gap))}</section>`+(a.coverage!=null&&a.coverage<1?notice(`<strong>Qualidade dos dados:</strong> cobertura CMV de ${pct(a.coverage)}. ${num(a.count-a.eligible_count)} registros sem custo válido ficam fora da margem e do lucro bruto.`):'')+comparison(items)+drivers(items)+`
 <section class="card" style="margin-bottom:20px"><div class="card-head"><div><h2>Trajetória dentro do período</h2><p class="small">Cada ponto respeita as datas selecionadas, inclusive meses parciais</p></div><span class="tag green">${hist.length} ${hist.length===1?'mês':'meses'}</span></div>${chart(hist,'margin','benchmark',false,'year')}<div class="legend"><span><i></i>Realizada</span><span><i class="other"></i>3 meses anteriores</span><span><i class="year"></i>Ano anterior</span></div><details><summary>Ver valores exatos e datas de cada ponto</summary><div class="table-wrap"><table><thead><tr><th>Período do ponto</th><th>Realizada</th><th>3M</th><th>Ano anterior</th><th>LB</th></tr></thead><tbody>${hist.map(h=>`<tr><td>${periodLabel([h.start,h.end])}</td><td>${pct(h.margin)}</td><td>${pct(h.benchmark)}</td><td>${pct(h.year)}</td><td>${brl(h.gross)}</td></tr>`).join('')}</tbody></table></div></details></section>
 <section class="card" style="margin-bottom:20px"><div class="card-head"><div><h2>Onde a margem acontece</h2><p class="small">Mesmo recorte de produtos nas três janelas · ordenado por gap agregado</p></div><label>Agrupar<select id="group"><option value="category" ${state.group==='category'?'selected':''}>Categoria</option><option value="type" ${state.group==='type'?'selected':''}>Tipo</option><option value="sku" ${state.group==='sku'?'selected':''}>Produto</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Grupo</th><th>Receita atual</th><th>Margem atual</th><th>3M</th><th>Ano anterior</th><th>Gap atual</th></tr></thead><tbody>${grouped.map(g=>`<tr><td><strong>${esc(g.name)}</strong></td><td>${brl(g.revenue)}</td><td><strong>${pct(g.margin)}</strong></td><td>${snapshot().complete.three?pct(g.three.margin):'Indisponível'}</td><td>${snapshot().complete.year?pct(g.year.margin):'Indisponível'}</td><td>${brl(g.gap)}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="card"><div class="section-line"><div><p class="eyebrow">PRÓXIMO PASSO</p><h2>Comece por estes sinais</h2><p class="small">Até 5 prioridades · maior gap verificável primeiro</p></div><span class="small">${signals.length} produtos com sinais</span></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Condição observada</th><th>Margem atual</th><th>3M</th><th>Ano anterior</th><th>Gap</th><th>Ação</th></tr></thead><tbody>${signals.slice(0,5).map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${i.sku} · ${esc(i.type)}</small></td><td><span class="tag ${i.severity==='Crítico'?'red':'amber'}">${i.severity}</span><small>${esc(i.alerts.slice(0,2).join(' · '))}</small></td><td>${pct(i.current.margin)}</td><td>${snapshot().complete.three?pct(i.three.margin):'Indisponível'}</td><td>${snapshot().complete.year?pct(i.year.margin):'Indisponível'}</td><td>${brl(i.current.gap)}</td><td><button class="link-button" data-investigate="${i.sku}">Investigar ↗</button></td></tr>`).join('')||'<tr><td colspan="7">Nenhum sinal nos filtros atuais.</td></tr>'}</tbody></table></div><p class="small" style="margin-top:12px">Gaps positivos por SKU não se compensam; o gap líquido da carteira permite compensação. Nenhum deles representa perda realizada.</p></section>
 <section class="card" style="margin-top:20px"><h2>Pendências de qualidade</h2><p class="small">Sem estimar valores ausentes</p><div class="quality-list">${items.filter(i=>i.current.count&&i.quality.length).map(i=>`<button class="quality-chip" data-investigate="${i.sku}">${esc(i.name)} · ${esc(i.quality[0])} ↗</button>`).join('')||'<span class="small">Nenhuma pendência para esta seleção.</span>'}</div></section>`;
}
function factText(f){if(!f)return '';const v=f.values;if(f.kind==='cost')return `O custo da última compra passou de ${brl(v.previous)} para ${brl(v.current)} (${pct(v.change)}), na mesma unidade.`;if(f.kind==='negative')return `O lucro bruto elegível foi ${brl(v.gross)}, com margem realizada de ${pct(v.margin)}.`;if(f.kind==='target')return `O gap elegível para a meta é ${brl(v.gap)}, com margem realizada de ${pct(v.margin)}.`;return `As vendas elegíveis somam ${brl(v.revenue)} em ${num(v.quantity)} unidades; desconto registrado de ${brl(v.discount)}.`;}
function narrative(item){
 const n=item.narrative;if(!n.response)return notice('Não há evidência suficiente para uma narrativa financeira. Confira a qualidade e os cálculos disponíveis.');
 const entries=[{mode:n.mode,response:n.response},...(n.supporting||[])];
 try{for(const e of entries)M.validateNarrative(e.response,n.facts,snapshot().period);}catch(e){return notice('Narrativa recusada pela barreira: '+esc(e.message),'error');}
 return entries.map((e,index)=>{const r=e.response,label=e.mode==='prepared'?'IA produzida previamente · verificada':'Texto automático de regras';return `<section class="narrative-entry" data-fact-kind="${esc(n.facts[r.fact_id].kind)}"><h3>${index===0?'Diagnóstico principal':'Fato complementar'}</h3><span class="tag green">${label}</span><div class="fact"><p><strong>${esc(factText(n.facts[r.fact_id]))}</strong></p><p>${esc(D.narrative_text[r.hypothesis])}</p><p class="small">Evidência: ${esc(r.fact_id)}</p></div><p>${esc(D.actions[r.action_code])}</p></section>`;}).join('')+'<p class="small">Prioridade: margem negativa → meta → custo → preço. Alternativas condicionadas às premissas. Sem garantia de demanda, ganho ou causalidade.</p>';
}
function diagnostic(items){if(!items.some(i=>i.current.count))return empty();const i=selectedItem();state.selected=i.sku;const a=i.current,p=i.purchase,price=a.quantity>0?a.revenue/a.quantity:null,hist=history([i]);const timeline=hist.map(h=>{const it=engine.analyze(h.start,h.end).items.find(x=>x.sku===i.sku);return {...h,price:h.quantity>0?h.revenue/h.quantity:null,purchase:it.purchase.valid?it.purchase.current.cost:null};});
 return comparison([i],'Histórico do produto em foco')+`<section class="card" style="margin-bottom:20px"><div class="card-head"><div><p class="eyebrow">Produto em foco: ${i.sku}${i.story?' (história '+i.story+')':''}</p><h2 class="detail-title">${esc(i.name)}</h2><p class="small">${esc(i.category)} · ${esc(i.type)} · unidade ${i.unit} · ${periodLabel(snapshot().windows.current)}</p></div><label>Trocar produto<select id="detail-sku">${options(items,i.sku)}</select></label></div><div class="pulse"><span>Realizada <b>${pct(a.margin)}</b></span><span>Meta coberta <b>${a.target_revenue>0?pct(a.target_value/a.target_revenue):'Indisponível'}</b></span><span>Gap <b>${brl(a.gap)}</b></span><span>Cobertura CMV <b>${pct(a.coverage)}</b></span><span>Confiança <b>${i.confidence}</b></span></div><div class="quality-list">${i.alerts.map(t=>`<span class="tag amber">${esc(t)}</span>`).join('')}</div></section>
 <div class="grid equal"><section class="card"><h2>O que os dados sustentam</h2><p class="small">Fato → hipótese limitada → alternativa de ação</p>${narrative(i)}<details><summary>Ver evidências e cálculo</summary><div class="formula">LB = ${brl(a.eligible_revenue)} − ${brl(a.cmv)} = ${brl(a.gross)}<br>Margem = LB ÷ receita elegível = ${pct(a.margin)}<br>Gap = máx(0; ${brl(a.target_value)} − ${brl(a.target_gross)}) = ${brl(a.gap)}</div><p class="small">${a.eligible_count} / ${a.count} registros elegíveis. Cobertura da meta: ${a.eligible_revenue>0?pct(a.target_revenue/a.eligible_revenue):'Indisponível'}. Valores ausentes não viram zero.</p><pre>${esc(JSON.stringify({period:snapshot().windows.current,source_ids:i.source_ids,source_rows:i.source_rows,facts:i.narrative.facts,dataset_hash:D.dataset_hash},null,2))}</pre></details></section>
 <section class="card"><h2>Da investigação à decisão</h2><div class="recommendation"><span class="step">1</span><div><strong>Conferir a origem</strong><p class="small">${i.quality.length?esc(i.quality.join('; ')):'Custos e unidades elegíveis. Confirme a política de meta e a base de comissão.'}</p></div></div><div class="recommendation"><span class="step">2</span><div><strong>Separar compra de venda</strong><p class="small">A última compra altera a margem teórica. O CMV registrado das vendas não é reescrito.</p></div></div><div class="recommendation"><span class="step">3</span><div><strong>Comparar alternativas</strong><p class="small">Mude preço, custo e volume como hipóteses. Margem maior não assegura maior lucro.</p></div></div><button class="button" data-simulate="${i.sku}" ${!i.simulation?'disabled':''}>Simular correção →</button>${!i.simulation?'<p class="small">Sem CMV elegível, a simulação automática fica indisponível.</p>':''}<p class="small" style="margin-top:16px">As recomendações não efetivam nenhum reajuste.</p></section></div>
 <div class="grid equal"><section class="card"><h2>Preço líquido × custo de compra</h2><p class="small">${i.unit} · a curva de compra é teórica, não o CMV realizado</p>${chart(timeline,'price','purchase',true)}<div class="legend"><span><i></i>Preço líquido por unidade</span><span><i class="other"></i>Última compra comparável</span></div><details><summary>Ver linha do tempo e datas de compra</summary><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Preço</th><th>Custo compra</th><th>Compra em</th><th>Margem realizada</th></tr></thead><tbody>${timeline.map(h=>{const buy=engine.analyze(h.start,h.end).items.find(x=>x.sku===i.sku).purchase;return `<tr><td>${month(h.month)}</td><td>${brl(h.price)}</td><td>${brl(h.purchase)}</td><td>${buy.valid?date(buy.current.date):'Indisponível'}</td><td>${pct(h.margin)}</td></tr>`;}).join('')}</tbody></table></div></details></section>
 <section class="card"><h2>O efeito da última compra</h2><p class="small">Preço constante · somente mesmo SKU e unidade</p>${p.valid&&price?`<div class="delta-grid"><div><span class="small">Penúltima · ${date(p.previous.date)}</span><b>${brl(p.previous.cost)}</b><span class="small">Teórica: ${pct((price-p.previous.cost)/price)}</span></div><div><span class="small">Última · ${date(p.current.date)}</span><b>${brl(p.current.cost)}</b><span class="small">Teórica: ${pct((price-p.current.cost)/price)}</span></div></div><div class="fact"><strong>Custo ${pct(p.change)} · margem teórica ${pp((p.previous.cost-p.current.cost)/price)}</strong><p class="small">Preço fixado em ${brl(price)}. Essa variação não reescreve a margem realizada de ${pct(a.margin)}.</p></div>`:notice(esc(p.reason||'Preço líquido indisponível'))}<details><summary>Testar uma resposta incorreta da IA</summary><p class="small">Fixture adversarial simulada: adiciona um valor não autorizado à resposta. Não é uma chamada ao modelo.</p><button class="button secondary" id="test-barrier">Executar teste da barreira</button><div id="barrier-result" role="status"></div></details></section></div>`;
}
let simErr={};
function simulator(items){if(!items.some(i=>i.current.count))return empty();const i=selectedItem();state.selected=i.sku;if(!i.simulation)return comparison([i],'Histórico do produto em foco')+`<section class="card"><h2>${esc(i.name)}: custo elegível indisponível</h2>${notice('Não preenchemos CMV desconhecido. Selecione outro produto ou corrija a origem antes de simular.')}<label>Produto<select id="detail-sku">${options(items,i.sku)}</select></label></section>`;
 const base=i.simulation;if(!simInput){simErr={};let ref=base.p;try{ref=Math.max(base.p,M.simulate(base).reference_price);}catch(e){}simInput={...base,p:ref,volumeDown:10,volumeUp:10};}const s=simInput;
 return comparison([i],'Histórico realizado · antes de simular')+`<div class="sim-layout"><section class="card"><p class="eyebrow">Premissas do cenário</p><h2>${esc(i.name)}</h2><p class="small">${i.sku} · ${i.unit} · ${periodLabel(snapshot().windows.current)}</p><label>Trocar produto<select id="detail-sku">${options(items,i.sku)}</select></label><p class="small" style="margin-top:13px">Referência calculada por preço e CMV unitários médios do mesmo SKU, arredondados a centavos. Não aplica um custo único a produtos diferentes.</p><div class="controls"><label class="wide">Novo preço líquido (R$)<input id="sim-p" type="number" min="0.01" max="1000000" step="0.01" value="${(s.p/100).toFixed(2)}"><input id="price-range" aria-label="Ajustar preço líquido" type="range" min="${Math.max(1,Math.floor(base.p*.5))/100}" max="${Math.ceil(base.p*2)/100}" step="0.01" value="${s.p/100}"></label><label>Meta escolhida<select id="sim-goal"><option value="gross" ${s.goal==='gross'?'selected':''}>Margem bruta</option><option value="channel" ${s.goal==='channel'?'selected':''}>Pós-comissão</option></select></label><label>Margem-alvo (%)<input id="sim-m" type="number" min="0" max="99.99" step="0.01" value="${s.m/100}"></label></div><details open><summary>Custo, volume e comissão</summary><div class="controls"><label>CMV unitário (R$)<input id="sim-c" type="number" min="0" max="1000000" step="0.01" value="${s.c/100}"></label><label>Volume (${i.unit})<input id="sim-q" type="number" min="0" max="1000000" step="1" value="${s.q}"></label><label>Comissão do canal (%)<input id="sim-t" type="number" min="0" max="99.99" step="0.01" value="${s.t/100}"></label><label>Queda conservadora (%)<input id="sim-down" type="number" min="0" max="100" step="1" value="${s.volumeDown}"></label><label>Ganho otimista (%)<input id="sim-up" type="number" min="0" max="100" step="1" value="${s.volumeUp}"></label></div></details><button id="use-reference" class="button secondary" style="margin-top:20px">Usar preço-referência da meta</button><button id="reset-sim" class="quiet" style="display:block;margin-top:10px">↺ Restaurar premissas do produto</button></section>
 <section><div id="simulation-results" aria-live="polite"></div><section class="card" style="margin-top:20px"><h2>O que estamos assumindo</h2><p class="small">Comissão proporcional ao preço líquido. Impostos, frete, despesas fixas, devoluções e elasticidade estão fora deste cenário. Resultado pós-canal é simplificado, não lucro líquido.</p><p class="small">Conservador e otimista usam mudanças de volume definidas por você. São sensibilidades, não previsões.</p><details><summary>Ver fórmulas</summary><div class="formula">Receita = p × q<br>CMV = c × q<br>LB = (p − c) × q<br>Margem bruta = (p − c) ÷ p<br>Resultado pós-canal = Receita − CMV − comissão<br>Preço para meta bruta = c ÷ (1 − m)<br>Preço para meta pós-canal = c ÷ (1 − t − m)</div><p class="small">Preço-referência arredondado para cima ao centavo. Comissão total arredondada ao centavo (HALF_UP). Fórmula ${D.formula}.</p></details><button id="copy-scenario" class="button secondary" style="margin-top:18px">Copiar cenário e premissas</button><textarea id="scenario-text" rows="6" aria-label="Resumo do cenário para copiar" readonly hidden></textarea></section></section></div>`;
}
function updateSimulation(){const i=selectedItem(),s=simInput;if(!s||!i.simulation)return;try{
 const bad=Object.values(simErr).find(Boolean);for(const k of ['p','c','q','t','m'])$('sim-'+k)?.setAttribute('aria-invalid',simErr[k]?'true':'false');if(bad)throw Error(bad);
 const r=M.simulate(i.simulation),p=M.simulate(s);if(!Number.isFinite(s.volumeDown)||s.volumeDown<0||s.volumeDown>100||!Number.isFinite(s.volumeUp)||s.volumeUp<0||s.volumeUp>100)throw Error('Variação de volume deve estar entre 0% e 100%.');
 const con=M.simulate({...s,q:Math.round(s.q*(1-s.volumeDown/100))}),opt=M.simulate({...s,q:Math.round(s.q*(1+s.volumeUp/100))});
 const metrics=[['Receita','revenue',brl],['CMV','cmv',brl],['Lucro bruto','gross',brl],['Margem bruta','gross_margin',pct],['Comissão','commission',brl],['Resultado pós-canal','channel',brl],['Margem pós-canal','channel_margin',pct]];
 const unit=s.p-s.c,q0=i.simulation.q,qe=unit>0&&r.gross>0?r.gross/unit:null,be=qe==null?'':`<div class="fact"><p>Volume de equilíbrio: <b>${num(Math.ceil(qe))} ${i.unit}</b> (${qe<=q0?'pode perder até '+pct(1-qe/q0)+' do volume':'precisa de +'+pct(qe/q0-1)+' de volume'} antes de o lucro bruto ficar abaixo do atual).</p><p class="small">Cálculo exato, sem previsão de demanda. Queda e ganho de volume abaixo são hipóteses suas.</p></div>`;
 const comparison=metrics.map(([name,key,fmt])=>`<tr><td>${name}</td><td>${fmt(r[key])}</td><td><strong>${fmt(p[key])}</strong></td><td>${key.includes('margin')?pp(p[key]-r[key]):brl(p[key]-r[key])}</td></tr>`).join('');
 $('simulation-results').innerHTML=`<div class="sim-result"><span class="small">Preço-referência para ${pct(s.m/10000)} ${s.goal==='gross'?'de margem bruta':'pós-comissão'}</span><strong>${brl(p.reference_price)}</strong><p class="small">Referência matemática, não recomendação comercial.</p></div>${be}${p.gross<0?notice('Atenção: o cenário proposto tem margem bruta negativa.'):''}${s.q===0?notice('Quantidade nula: nenhum resultado monetário. A margem exibida é unitária.'):''}${Math.abs(s.p/i.simulation.p-1)>.5?notice('Variação de preço acima de 50%: revise a hipótese de volume.'):''}<section class="card"><h2>Atual × proposto</h2><div class="table-wrap"><table class="scenario-table"><thead><tr><th>Indicador</th><th>Referência</th><th>Proposto</th><th>Variação</th></tr></thead><tbody>${comparison}</tbody></table></div><p class="small" style="margin-top:14px">Sob as premissas informadas, LB varia ${brl(p.gross-r.gross)} (${r.gross>0?growth(p.gross,r.gross):'% não aplicável'}), e o resultado pós-canal varia ${brl(p.channel-r.channel)}. Isso não prevê aceitação do novo preço.</p></section><section class="card" style="margin-top:18px"><h2>Sensibilidade ao volume</h2><div class="table-wrap"><table><thead><tr><th>Cenário</th><th>Unidades</th><th>LB</th><th>Pós-canal</th></tr></thead><tbody><tr><td>Referência</td><td>${num(i.simulation.q)}</td><td>${brl(r.gross)}</td><td>${brl(r.channel)}</td></tr><tr><td>Conservador · −${s.volumeDown}%</td><td>${num(Math.round(s.q*(1-s.volumeDown/100)))}</td><td>${brl(con.gross)}</td><td>${brl(con.channel)}</td></tr><tr class="selected-row"><td>Proposto</td><td>${num(s.q)}</td><td>${brl(p.gross)}</td><td>${brl(p.channel)}</td></tr><tr><td>Otimista · +${s.volumeUp}%</td><td>${num(Math.round(s.q*(1+s.volumeUp/100)))}</td><td>${brl(opt.gross)}</td><td>${brl(opt.channel)}</td></tr></tbody></table></div></section>`;
 lastScenario=JSON.stringify({timestamp:new Date().toISOString(),formula:D.formula,sku:i.sku,filters:state,reference:i.simulation,proposed:s,results:p,limits:'Dados fictícios. Volume hipotético; sem impostos, frete, despesas fixas, devoluções ou elasticidade. Não é previsão nem lucro líquido.'},null,2);
 }catch(e){$('simulation-results').innerHTML=notice(esc(e.message),'error');lastScenario='';}}
function bindView(){document.querySelectorAll('[data-investigate]').forEach(b=>b.onclick=()=>choose(b.dataset.investigate,'diagnostic'));document.querySelectorAll('[data-simulate]').forEach(b=>b.onclick=()=>choose(b.dataset.simulate,'simulator'));document.querySelector('[data-clear]')?.addEventListener('click',resetFilters);$('group')?.addEventListener('change',e=>{state.group=e.target.value;render();});$('detail-sku')?.addEventListener('change',e=>{state.selected=e.target.value;simInput=null;render();});$('test-barrier')?.addEventListener('click',()=>{const n=selectedItem().narrative;try{M.validateNarrative({...n.response,invented_value:999999},n.facts,snapshot().period);$('barrier-result').innerHTML=notice('Erro de teste: resposta deveria ser recusada.','error');}catch(e){$('barrier-result').innerHTML=notice('Recusada: '+esc(e.message)+'. Modo final: texto automático de regras.','good')+`<p class="small">${esc(n.response?factText(n.facts[n.response.fact_id]):'Sem evidência: apenas alerta de qualidade.')}</p>`;}});
 if(state.tab==='simulator'&&simInput){const map={p:100,c:100,q:1,t:100,m:100};for(const [key,mult] of Object.entries(map))$('sim-'+key)?.addEventListener('input',e=>{const v=e.target.valueAsNumber;const okv=Number.isFinite(v)&&Math.abs(v*mult-Math.round(v*mult))<1e-6;simErr[key]=e.target.value===''?'Informe um valor.':Number.isFinite(v)&&!okv?(key==='q'?'Use um número inteiro.':'Use no máximo 2 casas decimais.'):'';simInput[key]=okv?Math.round(v*mult):NaN;if(simErr[key]){updateSimulation();return;}if(key==='p')$('price-range').value=v;updateSimulation();});$('sim-goal').onchange=e=>{simInput.goal=e.target.value;updateSimulation();};$('price-range').oninput=e=>{simInput.p=Math.round(+e.target.value*100);$('sim-p').value=e.target.value;updateSimulation();};for(const [key,field] of [['down','volumeDown'],['up','volumeUp']])$('sim-'+key).oninput=e=>{simInput[field]=e.target.valueAsNumber;updateSimulation();};$('use-reference').onclick=()=>{try{const result=M.simulate(simInput);simInput.p=Math.max(1,result.reference_price);$('sim-p').value=simInput.p/100;$('price-range').value=simInput.p/100;updateSimulation();}catch(e){$('simulation-results').innerHTML=notice(esc(e.message),'error');}};$('reset-sim').onclick=()=>{simInput=null;render();};$('copy-scenario').onclick=async()=>{if(!lastScenario)return;$('scenario-text').hidden=false;$('scenario-text').value=lastScenario;try{await navigator.clipboard.writeText(lastScenario);$('copy-scenario').textContent='Cenário copiado ✓';}catch(e){$('scenario-text').focus();$('scenario-text').select();$('copy-scenario').textContent='Selecione e copie o resumo abaixo';}};updateSimulation();}}
function available(){return snapshot().items.filter(i=>i.current.count&&(!state.category||i.category===state.category)&&(!state.type||i.type===state.type));}
function reconcile(){const snap=snapshot(),cats=new Set(snap.items.filter(i=>i.current.count).map(i=>i.category));if(state.category&&!cats.has(state.category)){state.category='';filterMessage='A categoria foi removida porque não tem movimento no novo período.';}const types=new Set(snap.items.filter(i=>i.current.count&&(!state.category||i.category===state.category)).map(i=>i.type));if(state.type&&!types.has(state.type)){state.type='';filterMessage='O tipo foi removido porque não tem produtos disponíveis neste recorte.';}if(state.sku&&!available().some(i=>i.sku===state.sku)){state.sku='';filterMessage='O produto anterior não pertence ao novo recorte. Exibindo todos os produtos disponíveis.';}const valid=selectedItems().filter(i=>i.current.count);if(!valid.some(i=>i.sku===state.selected)){state.selected=valid[0]?.sku||'';simInput=null;}}
let suggestionIndex=-1,suggestions=[];
const fold=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function closeSuggestions(){$('sku-list').hidden=true;$('sku-search').setAttribute('aria-expanded','false');$('sku-search').removeAttribute('aria-activedescendant');suggestionIndex=-1;}
function selectSku(sku){state.sku=sku;state.selected=sku;simInput=null;closeSuggestions();filterMessage='';render();$('sku-search').focus();}
function suggest(){const q=fold($('sku-search').value.trim());suggestions=available().filter(i=>fold(i.sku+' '+i.name).includes(q));suggestionIndex=-1;$('sku-list').hidden=false;$('sku-search').setAttribute('aria-expanded','true');$('sku-search').removeAttribute('aria-activedescendant');$('sku-list').innerHTML=suggestions.map((i,n)=>`<li id="sku-option-${n}" role="option" aria-selected="false" data-option="${esc(i.sku)}"><strong>${esc(i.name)}</strong><small>${i.sku} · ${esc(i.category)} · ${esc(i.type)}</small></li>`).join('')||'<li class="no-option" role="presentation">Nenhum produto corresponde à busca neste recorte.</li>';document.querySelectorAll('[data-option]').forEach(el=>el.onmousedown=e=>{e.preventDefault();selectSku(el.dataset.option);});document.querySelectorAll('[data-option]').forEach(el=>el.onclick=()=>selectSku(el.dataset.option));}
function sync(){
 $('date-start').value=state.start;$('date-end').value=state.end;
 const items=snapshot().items,cat=Array.from(new Set(items.filter(i=>i.current.count).map(i=>i.category))).sort();$('category').innerHTML='<option value="">Todas as categorias</option>'+cat.map(c=>`<option value="${esc(c)}" ${c===state.category?'selected':''}>${esc(c)}</option>`).join('');$('category').value=state.category;
 document.querySelectorAll('[data-type]').forEach(b=>{const n=items.filter(i=>i.current.count&&i.type===b.dataset.type&&(!state.category||i.category===state.category)).length;b.setAttribute('aria-pressed',String(state.type===b.dataset.type));b.disabled=!n;b.innerHTML=esc(b.dataset.type)+` <span>${n}</span>`;});$('type-caption').textContent=state.type?'Clique novamente para mostrar todos':'Nenhum ativo = todos os tipos';
 const selected=items.find(i=>i.sku===state.sku);$('sku-search').value=selected?selected.name+' · '+selected.sku:'';$('clear-sku').hidden=!state.sku;$('sku-caption').textContent=state.sku?'Produto selecionado em todas as abas':available().length+' produtos disponíveis · digite para buscar';closeSuggestions();$('selection-count').textContent=selectedItems().filter(i=>i.current.count).length+' produtos com movimento';
 $('date-error').hidden=true;for(const id of ['date-start','date-end'])$(id).setAttribute('aria-invalid','false');
}
function render(){try{if(!titles[state.tab])state.tab='executive';if(!['category','type','sku'].includes(state.group))state.group='category';reconcile();sync();$('page-title').textContent=titles[state.tab][0];$('subtitle').textContent=titles[state.tab][1];document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-current',b.dataset.tab===state.tab?'page':'false');});$('period-note').textContent='Entre '+date(state.start)+' e '+date(state.end)+' · '+(state.category||'Todas as categorias')+' · '+(state.type||'Todos os tipos')+' · filtros mantidos ao trocar de aba.';$('notice').innerHTML=filterMessage?notice(esc(filterMessage),'good'):'';const items=selectedItems();$('view').innerHTML=!items.some(i=>i.current.count)?empty():state.tab==='executive'?executive(items):state.tab==='diagnostic'?diagnostic(items):simulator(items);bindView();persist();}catch(e){$('view').innerHTML=notice('Não foi possível preparar esta seleção. Use Limpar filtros para restaurar a análise.','error');console.error(e);}}
function changeDates(){const s=$('date-start').value,e=$('date-end').value;try{E.parse(s);E.parse(e);if(s>e)throw Error('A data inicial deve ser anterior ou igual à final.');if(s<D.raw.history_start||e>D.as_of)throw Error('Escolha datas entre '+date(D.raw.history_start)+' e '+date(D.as_of)+'.');state.start=s;state.end=e;simInput=null;filterMessage='';render();}catch(error){$('date-error').hidden=false;$('date-error').textContent=error.message+' A análise abaixo mantém o último intervalo válido.';for(const id of ['date-start','date-end'])$(id).setAttribute('aria-invalid','true');}}
function resetFilters(){const tab=state.tab;state={...initial,tab};simInput=null;filterMessage='';render();}
function start(){if(!D||!M||!E)throw Error('Arquivos da demonstração ausentes');for(const id of ['date-start','date-end']){$(id).min=D.raw.history_start;$(id).max=D.as_of;$(id).onchange=changeDates;}
 $('category').onchange=e=>{state.category=e.target.value;simInput=null;filterMessage='';render();};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.type=state.type===b.dataset.type?'':b.dataset.type;simInput=null;filterMessage='';render();});
 $('sku-search').oninput=suggest;$('sku-search').onfocus=()=>{if(!state.sku)suggest();};$('sku-search').onkeydown=e=>{if(e.key==='Escape'){closeSuggestions();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if($('sku-list').hidden)suggest();if(!suggestions.length)return;suggestionIndex=(suggestionIndex+(e.key==='ArrowDown'?1:-1)+suggestions.length)%suggestions.length;document.querySelectorAll('[data-option]').forEach((el,n)=>el.setAttribute('aria-selected',String(n===suggestionIndex)));$('sku-search').setAttribute('aria-activedescendant','sku-option-'+suggestionIndex);}if(e.key==='Enter'&&!$('sku-list').hidden){e.preventDefault();if(suggestions.length)selectSku(suggestions[Math.max(0,suggestionIndex)].sku);}};
 $('sku-search').onblur=e=>{if(!e.relatedTarget||!$('sku-list').contains(e.relatedTarget)){closeSuggestions();const i=snapshot().items.find(i=>i.sku===state.sku);$('sku-search').value=i?i.name+' · '+i.sku:'';}};
 $('clear-sku').onclick=()=>{state.sku='';simInput=null;filterMessage='';render();};
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;filterMessage='';render();});$('reset').onclick=resetFilters;
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{state.end=D.as_of;state.start=b.dataset.preset==='month'?D.as_of.slice(0,7)+'-01':b.dataset.preset==='year'?D.as_of.slice(0,4)+'-01-01':E.add(D.as_of,-89);simInput=null;filterMessage='';render();});render();}
try{start();}catch(e){console.error(e);$('view').innerHTML=notice('Arquivos incompletos. Extraia o ZIP inteiro e abra ABRIR_DEMONSTRACAO.html.','error');}
